INSERT INTO `lucky_wheels` (`id`, `name`, `slug`, `thumbnail`, `wheel_image`, `pointer_image`, `description`, `rules`, `active`, `price_per_spin`, `config`, `created_at`, `updated_at`) VALUES
(1, 'Vòng Quay Vàng', 'vong-quay-vang', 'https://i.postimg.cc/xTNX3NHP/u-KLBf-Y8j-Wr-1630159016.gif', 'https://img.upanh.tv/2025/04/03/LVNwJbtFqU_1599464163-removebg-preview6c5e709413be5b98.png', NULL, 'Bạn có thể tham gia vòng quay để có cơ hội nhận được vàng hoặc ngọc. Mỗi lần bạn quay sẽ tốn 10,000 VNĐ, và đây là một cơ hội tuyệt vời để thử vận may của mình. Hãy tham gia ngay để không bỏ lỡ những phần thưởng hấp dẫn đang chờ đón bạn.', '<p>Quay để nhận vàng hoặc ngọc. Mỗi lần quay tốn 10,000 VNĐ.</p>', 1, 10000, '[{\"type\":\"gold\",\"content\":\"Tr\\u00fang 1 t\\u1ef7 v\\u00e0ng\",\"amount\":1000000000,\"probability\":10},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 50 tri\\u1ec7u v\\u00e0ng\",\"amount\":50000000,\"probability\":15},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 75 tri\\u1ec7u v\\u00e0ng\",\"amount\":75000000,\"probability\":20},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 100 tri\\u1ec7u v\\u00e0ng\",\"amount\":100000000,\"probability\":25},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 130 tri\\u1ec7u v\\u00e0ng\",\"amount\":130000000,\"probability\":10},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 200 tri\\u1ec7u v\\u00e0ng\",\"amount\":200000000,\"probability\":5},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 250 tri\\u1ec7u v\\u00e0ng\",\"amount\":250000000,\"probability\":5},{\"type\":\"gold\",\"content\":\"Tr\\u00fang 500 tri\\u1ec7u v\\u00e0ng\",\"amount\":500000000,\"probability\":10}]', '2026-08-21 08:58:36', '2026-08-21 08:58:36'),
(2, 'Vòng Quay Ngọc', 'vong-quay-ngoc', 'https://i.postimg.cc/vZWDpR0g/z5986105444643-1bf089311b9e3a012cb4659a7e46fd7c.gif', 'https://i.postimg.cc/vmbDyPKP/spinTYOI.png', NULL, 'Quay để nhận vàng hoặc ngọc. Mỗi lần quay sẽ tốn 10,000 VNĐ. Hãy tham gia để có cơ hội nhận được những phần thưởng giá trị từ vòng quay này. Mỗi lượt quay sẽ mang đến cho bạn những trải nghiệm thú vị và cơ hội trúng thưởng hấp dẫn.', '<p>Quay để nhận vàng hoặc ngọc. Mỗi lần quay tốn 10,000 VNĐ.</p>', 1, 10000, '[{\"type\":\"gem\",\"content\":\"Tr\\u00fang 5000 ng\\u1ecdc\",\"amount\":5000,\"probability\":10},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 50 ng\\u1ecdc\",\"amount\":50,\"probability\":15},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 100 ng\\u1ecdc\",\"amount\":100,\"probability\":20},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 150 ng\\u1ecdc\",\"amount\":150,\"probability\":25},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 200 ng\\u1ecdc\",\"amount\":200,\"probability\":10},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 300 ng\\u1ecdc\",\"amount\":300,\"probability\":10},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 500 ng\\u1ecdc\",\"amount\":500,\"probability\":5},{\"type\":\"gem\",\"content\":\"Tr\\u00fang 1000 ng\\u1ecdc\",\"amount\":1000,\"probability\":5}]', '2026-08-21 08:58:36', '2026-08-21 08:58:36'),
(3, 'Vòng Quay May Mắn Test', 'vong-quay-may-man-test', 'https://i.postimg.cc/xTNX3NHP/u-KLBf-Y8j-Wr-1630159016.gif', 'https://i.postimg.cc/vmbDyPKP/spinTYOI.png', NULL, '<p>Mô tả test vòng quay may mắn</p>', '<p>Thể lệ test: 20.000đ một lượt quay nhận quà khủng.</p>', 1, 20000, '[{\"active\":true,\"content\":\"5000\",\"probability\":20,\"trial_probability\":10,\"reward_type\":\"item\",\"reward_item_id\":13,\"amount\":\"5000\"},{\"active\":true,\"content\":\"50\",\"probability\":10,\"trial_probability\":10,\"reward_type\":\"item\",\"reward_item_id\":13,\"amount\":\"50\"},{\"active\":true,\"content\":\"100\",\"probability\":5,\"trial_probability\":5,\"reward_type\":\"item\",\"reward_item_id\":13,\"amount\":\"100\"},{\"active\":true,\"content\":\"150\",\"probability\":30,\"trial_probability\":15,\"reward_type\":\"item\",\"reward_item_id\":13,\"amount\":\"150\"},{\"active\":true,\"content\":\"200\",\"probability\":10,\"trial_probability\":20,\"reward_type\":\"item\",\"reward_item_id\":9,\"amount\":\"200\"},{\"active\":true,\"content\":\"300\",\"probability\":5,\"trial_probability\":10,\"reward_type\":\"random_account\",\"reward_item_id\":null,\"amount\":\"300\"},{\"active\":true,\"content\":\"500\",\"probability\":10,\"trial_probability\":15,\"reward_type\":\"money\",\"reward_item_id\":null,\"amount\":\"500\"},{\"active\":true,\"content\":\"1000\",\"probability\":10,\"trial_probability\":15,\"reward_type\":\"money\",\"reward_item_id\":null,\"amount\":\"1000\"}]', '2026-08-21 09:02:22', '2026-08-22 08:54:25');
